@Experimental
enum AdaptiveDeclineReason {
	NONE,
	MISSING_METADATA,
	STICKY_FILTER,
	VOLATILE_FILTER,
	EXISTS_FILTER,
	SINGLE_LEGAL_DEPTH,
	TOO_MANY_CANDIDATES
}

@Experimental
final class AdaptiveFilterMetadata {
	static final int CHEAP = 1;
	static final int MEDIUM = 4;
	static final int EXPENSIVE = 16;
	static final int MAX_COMPOSITE_COST = 64;

	private static final AdaptiveFilterMetadata MISSING = new AdaptiveFilterMetadata(-1, -1L, 0, false,
			AdaptiveDeclineReason.MISSING_METADATA);

	final int filterId;
	final long requiredMask;
	final int estimatedCostUnits;
	final boolean adaptiveEligible;
	final AdaptiveDeclineReason declineReason;

	private AdaptiveFilterMetadata(int filterId, long requiredMask, int estimatedCostUnits, boolean adaptiveEligible,
			AdaptiveDeclineReason declineReason) {
		this.filterId = filterId;
		this.requiredMask = requiredMask;
		this.estimatedCostUnits = estimatedCostUnits;
		this.adaptiveEligible = adaptiveEligible;
		this.declineReason = declineReason;
	}

	static AdaptiveFilterMetadata eligible(int filterId, int estimatedCostUnits) {
		return new AdaptiveFilterMetadata(filterId, -1L, estimatedCostUnits, true, AdaptiveDeclineReason.NONE);
	}

	static AdaptiveFilterMetadata ineligible(int filterId, int estimatedCostUnits, AdaptiveDeclineReason reason) {
		return new AdaptiveFilterMetadata(filterId, -1L, estimatedCostUnits, false, reason);
	}

	static AdaptiveFilterMetadata missing() {
		return MISSING;
	}

	static AdaptiveFilterMetadata forFilter(int filterId, Filter filter) {
		ValueExpr condition = filter.getCondition();
		CostClassifier classifier = new CostClassifier();
		condition.visit(classifier);

		if (classifier.containsExists) {
			return ineligible(filterId, classifier.cost(), AdaptiveDeclineReason.EXISTS_FILTER);
		}
		if (!QueryEvaluationUtility.isRepeatableWithinPreparation(condition)) {
			return ineligible(filterId, classifier.cost(), AdaptiveDeclineReason.VOLATILE_FILTER);
		}
		return eligible(filterId, classifier.cost());
	}

	AdaptiveFilterMetadata withRequiredMask(long requiredMask) {
		if (this.requiredMask == requiredMask) {
			return this;
		}
		if (requiredMask < 0L) {
			return new AdaptiveFilterMetadata(filterId, requiredMask, estimatedCostUnits, false,
					AdaptiveDeclineReason.STICKY_FILTER);
		}
		return new AdaptiveFilterMetadata(filterId, requiredMask, estimatedCostUnits, adaptiveEligible, declineReason);
	}

	private static final class CostClassifier extends AbstractQueryModelVisitor<RuntimeException> {
		private int units;
		private boolean containsExists;

		int cost() {
			return Math.max(CHEAP, Math.min(MAX_COMPOSITE_COST, units));
		}

		private void add(int value) {
			units = Math.min(MAX_COMPOSITE_COST, units + value);
		}

		@Override
		public void meet(Bound node) {
			add(CHEAP);
			super.meet(node);
		}

		@Override
		public void meet(ListMemberOperator node) {
			add(CHEAP);
			super.meet(node);
		}

		@Override
		public void meet(Compare node) {
			add(MEDIUM);
			super.meet(node);
		}

		@Override
		public void meet(MathExpr node) {
			add(MEDIUM);
			super.meet(node);
		}

		@Override
		public void meet(And node) {
			add(MEDIUM);
			super.meet(node);
		}

		@Override
		public void meet(Or node) {
			add(MEDIUM);
			super.meet(node);
		}

		@Override
		public void meet(Not node) {
			add(MEDIUM);
			super.meet(node);
		}

		@Override
		public void meet(Regex node) {
			add(EXPENSIVE);
			super.meet(node);
		}

		@Override
		public void meet(FunctionCall node) {
			String uri = node.getURI();
			add(uri != null && uri.startsWith(XSD.NAMESPACE) ? MEDIUM : EXPENSIVE);
			super.meet(node);
		}

		@Override
		public void meet(Exists node) {
			containsExists = true;
			add(EXPENSIVE);
			super.meet(node);
		}
	}
}

@Experimental
final class FilterPlacementEnvelope {
	static final int MAX_CANDIDATES = 8;

	final int filterId;
	final int plannedDepth;
	final int legalDepthCount;
	final int earliestLegalDepth;
	final int deepestLegalDepth;
	final int[] candidateDepths;

	FilterPlacementEnvelope(int filterId, int[] candidateDepths) {
		this(filterId, candidateDepths[candidateDepths.length - 1], candidateDepths.length, candidateDepths);
	}

	FilterPlacementEnvelope(int filterId, int plannedDepth, int legalDepthCount, int[] candidateDepths) {
		this.filterId = filterId;
		this.plannedDepth = plannedDepth;
		this.legalDepthCount = legalDepthCount;
		this.candidateDepths = candidateDepths;
		this.earliestLegalDepth = candidateDepths[0];
		this.deepestLegalDepth = candidateDepths[candidateDepths.length - 1];
	}

	@Override
	public String toString() {
		return "FilterPlacementEnvelope{filterId=" + filterId + ", candidateDepths="
				+ Arrays.toString(candidateDepths) + '}';
	}
}

@Experimental
record PlacementState(long generation, int activeDepth) {
}

/** Delegates evaluation while leaving filter lifetime with the surrounding factorized cursor. */
@Experimental
final class NonOwningAdaptiveFilter implements NativeBooleanFilter {
	private final NativeBooleanFilter delegate;

	NonOwningAdaptiveFilter(NativeBooleanFilter delegate) {
		this.delegate = delegate;
	}

	@Override
	public boolean accept(RowState row) {
		return delegate.accept(row);
	}

	@Override
	public int selectBatch(NativeBatch batch, int[] sel, int n, RowState scratch) {
		return delegate.selectBatch(batch, sel, n, scratch);
	}

	@Override
	public long batchReadMask() {
		return delegate.batchReadMask();
	}

	@Override
	public void close() {
		// The factorized prefix/branch owner closes the compiled filter exactly once.
	}
}

